/**
 * The components each recipe pattern is built from, generated by `pnpm site`
 * from the pattern's own imports (see `scripts/sitegen.ts`). The glob lives in
 * a `.ts` module, not in the page, so no `.tsx` file carries a glob call.
 */
const manifests = import.meta.glob<{
  components: { name: string; slug: string; href: string }[]
}>('../generated/sources/pattern-*.json', { import: 'default' })

export async function patternComponents(
  slug: string,
): Promise<{ name: string; slug: string; href: string }[]> {
  const load = manifests[`../generated/sources/pattern-${slug}.json`]
  return load ? (await load()).components : []
}
